defmodule Orax.Integration.ReturningTest do
  use ExUnit.Case, async: false

  @moduletag :oracle

  import Ecto.Query

  alias Orax.Integration
  alias Orax.Integration.Repo

  defmodule Item do
    use Ecto.Schema

    schema "orax_it_returning" do
      field :name, :string
      field :qty, :integer
    end
  end

  setup_all do
    start_supervised!({Repo, Integration.config()})
    Integration.drop_table(Repo, "orax_it_returning")

    Repo.query!(
      "CREATE TABLE orax_it_returning (id INTEGER GENERATED BY DEFAULT AS IDENTITY " <>
        "PRIMARY KEY, name VARCHAR2(20), qty INTEGER)"
    )

    on_exit(fn ->
      Integration.with_repo(Repo, fn ->
        Integration.drop_table(Repo, "orax_it_returning")
      end)
    end)

    :ok
  end

  test "insert, update and delete return several fields" do
    {:ok, item} = Repo.insert(%Item{name: "a", qty: 1}, returning: [:id, :name, :qty])
    assert %Item{id: id, name: "a", qty: 1} = item
    assert is_integer(id)

    {:ok, item} =
      item |> Ecto.Changeset.change(qty: 2) |> Repo.update(returning: [:name, :qty])

    assert %Item{id: ^id, name: "a", qty: 2} = item

    assert {:ok, %Item{name: "a", qty: 2}} = Repo.delete(item, returning: [:name, :qty])
    assert Repo.get(Item, id) == nil
  end

  test "raw queries with out binds keep one list per bind" do
    Repo.insert!(%Item{name: "b", qty: 5})

    assert %{rows: [[_id], [5]]} =
             Repo.query!(
               "UPDATE orax_it_returning SET qty = qty WHERE name = 'b' RETURN id, qty INTO :id, :qty",
               [],
               out: [:integer, :integer]
             )
  end

  test "update_all and delete_all with select raise before reaching the database" do
    item = Repo.insert!(%Item{name: "c", qty: 7})
    query = from(i in Item, where: i.id == ^item.id, select: i.qty)

    assert_raise Ecto.QueryError, ~r/:select is not supported in update_all/, fn ->
      Repo.update_all(query, set: [qty: 8])
    end

    assert_raise Ecto.QueryError, ~r/:select is not supported in delete_all/, fn ->
      Repo.delete_all(query)
    end

    assert %Item{qty: 7} = Repo.get!(Item, item.id)
    assert {1, nil} = Repo.update_all(from(i in Item, where: i.id == ^item.id), set: [qty: 8])
    assert %Item{qty: 8} = Repo.get!(Item, item.id)
  end

  test "FOR UPDATE returns every locked row" do
    for n <- 1..3, do: Repo.insert!(%Item{name: "lock", qty: n})
    query = from(i in Item, where: i.name == "lock", order_by: i.qty, select: i.qty)

    assert {:ok, [1, 2, 3]} =
             Repo.transaction(fn -> query |> lock("FOR UPDATE") |> Repo.all() end)

    assert {:ok, [1, 2, 3]} =
             Repo.transaction(fn -> query |> lock("FOR UPDATE SKIP LOCKED") |> Repo.all() end)
  end

  defp names(prefix) do
    Repo.all(from i in Item, where: like(i.name, ^"#{prefix}%"), order_by: i.id, select: {i.name, i.qty})
  end

  test "insert_all of several rows returns the values of every row" do
    assert {3, [%{id: id1, name: "ia"}, %{id: id2, name: "ib"}, %{id: id3, name: "ic"}]} =
             Repo.insert_all(Item, [%{name: "ia", qty: 1}, %{name: "ib", qty: nil}, %{name: "ic", qty: 3}],
               returning: [:id, :name])

    assert id1 < id2 and id2 < id3
    assert names("i") == [{"ia", 1}, {"ib", nil}, {"ic", 3}]
    assert {2, nil} = Repo.insert_all(Item, [%{name: "id", qty: 4}, %{name: "ie", qty: 5}])
  end

  test "insert_all of rows that leave out different fields keeps their order" do
    rows = [%{name: "ha", qty: 1}, %{name: "hb"}, %{name: "hc"}, %{name: "hd", qty: 4}]

    assert {4, returned} = Repo.insert_all(Item, rows, returning: [:id])
    assert returned |> Enum.map(& &1.id) |> Enum.sort() == Enum.map(returned, & &1.id)
    assert names("h") == [{"ha", 1}, {"hb", nil}, {"hc", nil}, {"hd", 4}]
  end

  test "insert_all that fails on a row inserts none of them" do
    Repo.query!("ALTER TABLE orax_it_returning ADD CONSTRAINT orax_it_returning_qty CHECK (qty < 100)")
    on_exit(fn ->
      Repo.query!("ALTER TABLE orax_it_returning DROP CONSTRAINT orax_it_returning_qty")
    end)

    bad = [%{name: "fa", qty: 1}, %{name: "fb", qty: 2}, %{name: "fc", qty: 100}]
    assert_raise DBConnection.ConnectionError, ~r/ORA-02290/, fn -> Repo.insert_all(Item, bad) end
    assert names("f") == []

    mixed = [%{name: "fd", qty: 1}, %{name: "fe"}, %{name: "ff", qty: 100}]
    assert_raise DBConnection.ConnectionError, ~r/ORA-02290/, fn -> Repo.insert_all(Item, mixed) end
    assert names("f") == []

    assert {:ok, :done} =
             Repo.transaction(fn ->
               Repo.insert!(%Item{name: "fg", qty: 7})

               assert_raise DBConnection.ConnectionError, ~r/ORA-02290/, fn ->
                 Repo.insert_all(Item, bad)
               end

               :done
             end)

    assert names("f") == [{"fg", 7}]
  end

  test "insert_all with on_conflict other than :raise is not supported" do
    assert_raise ArgumentError, ~r/:on_conflict is not supported by Oracle/, fn ->
      Repo.insert_all(Item, [%{name: "oc", qty: 1}], on_conflict: :nothing)
    end
  end
end
